param([Parameter(Mandatory)][string]$Executable,[Parameter(Mandatory)][string]$ProviderExecutable,[Parameter(Mandatory)][string]$FixtureExecutable,[Parameter(Mandatory)][string]$ProjectRoot,[Parameter(Mandatory)][string]$ScratchRoot)
$ErrorActionPreference='Stop';$checks=0;$service=$null;$provider=$null
$root=Join-Path $ScratchRoot ('compaction-chunks-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null
[IO.File]::WriteAllText((Join-Path $root .synthetic-ai-evaluation),'hibernation.dialogue-evaluation.v1');$seed=& $FixtureExecutable $root long-memory;if($LASTEXITCODE-ne0){throw 'synthetic seed failed'}
$env:HIBERNATION_SESSION_KEY='chunks-synthetic-session';$headers=@{Authorization='Bearer '+$env:HIBERNATION_SESSION_KEY};$ready=Join-Path $root ready.json;$configPath=Join-Path $root config.json
function Check([bool]$Value,[string]$Name){if(!$Value){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Await([scriptblock]$Probe,[string]$Name){$end=[DateTime]::UtcNow.AddSeconds(40);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 30};throw "TIMEOUT: $Name"}
function Api($Path,$Data=$null){$p=@{Uri=$script:origin+$Path;Headers=$headers;TimeoutSec=10};if($null-ne$Data){$p.Method='Post';$p.ContentType='application/json; charset=utf-8';$p.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 60 -Compress))};Invoke-RestMethod @p}
function Start-Backend{$script:service=Start-Process -FilePath $Executable -ArgumentList ('--config "'+$configPath+'" --ready-file "'+$ready+'"') -WindowStyle Hidden -PassThru;Await {if($service.HasExited){throw 'chunk host exited'};if(Test-Path $ready){return (Get-Content $ready -Raw|ConvertFrom-Json).pid-eq$service.Id};$false} ready;$script:origin='http://127.0.0.1:'+((Get-Content $ready -Raw|ConvertFrom-Json).port)}
function Stop-Backend{$null=Api '/api/shutdown' @{};Check ($service.WaitForExit(15000)-and$service.ExitCode-eq0) 'clean chunk host exit'}
function Current{(Api '/api/memory-workshop').jobs|Where-Object id -eq $script:jobId}
try{
 $providerRoot=Join-Path $root provider;New-Item -ItemType Directory $providerRoot|Out-Null;$provider=Start-Process -FilePath $ProviderExecutable -ArgumentList ('"'+$providerRoot+'"') -WindowStyle Hidden -PassThru;Await {Test-Path (Join-Path $providerRoot port)} provider
 $digest=@{summary='对方描述一个仍有分歧的合成故事，否定和后来的纠正需要保留。';keywords=@('合成故事','纠正');uncertainties=@('故事仍未确认结论。')};@{responses=@(@{response=$digest;delay_ms=700})}|ConvertTo-Json -Depth 20|Set-Content (Join-Path $providerRoot plan.json) -Encoding utf8
 $cfg=Get-Content (Join-Path $ProjectRoot config/example.json) -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot=Join-Path $root data;$cfg.characterRoot=Join-Path $ProjectRoot character;$cfg.uiRoot=Join-Path $ProjectRoot ui;$cfg.pluginRoot=Join-Path (Split-Path $Executable) plugins;$cfg.plugins=@{};$cfg.computer=@{enabled=$false};$cfg.solitudeIntervalMs=604800000;$cfg.idleBeforeSolitudeMs=86400000;$cfg.profiles=@($cfg.profiles[0],@{id='manager';label='local chunks fixture';enabled=$true;protocol='chat-completions';origin=('http://127.0.0.1:'+(Get-Content (Join-Path $providerRoot port)));model='fixture-model';supportsJsonObject=$true;maxOutputTokens=2048;timeoutMs=10000});$cfg.review=@{enabled=$true;profileId='manager';maxRewrites=0};$cfg|ConvertTo-Json -Depth 60|Set-Content $configPath -Encoding utf8
 Start-Backend;$null=Api '/api/control' @{paused=$true};$jobId=(Api '/api/memory-workshop/jobs' @{type='distill';request_id='chunks';limit=1;minBytes=2000}).id
 Await {(Current).current_compaction.saved_chunks-ge1} 'first encrypted chunk checkpoint';$null=Api '/api/memory-workshop/control' @{id=$jobId;action='pause'};Await {(Current).status-eq'paused'} 'chunk pause'
 $partial=Current;$offset=$partial.current_compaction.processed_bytes;Check ($partial.completed_steps-eq0-and$offset-gt0-and$offset-lt$partial.current_compaction.total_bytes) 'a partly condensed original has a real byte cursor without a published summary'
 Check (@((Api '/api/memories').memories|Where-Object origin -eq library_compaction).Count-eq0) 'partial rolling digest is not exposed as a complete memory'
 Stop-Backend;Start-Backend;Check ((Current).current_compaction.processed_bytes-eq$offset-and(Current).status-eq'paused') 'encrypted partial digest and UTF-8 cursor survive restart'
 @{responses=@(@{response=$digest;delay_ms=0});nonce=[Guid]::NewGuid().ToString()}|ConvertTo-Json -Depth 20|Set-Content (Join-Path $providerRoot plan.json) -Encoding utf8
 $null=Api '/api/memory-workshop/control' @{id=$jobId;action='resume'};Await {(Current).status-in@('completed','failed')} 'finish long original';Check ((Current).status-eq'completed'-and(Current).saved_chunks-ge4) 'long memory finishes from its chunks and reports saved progress'
 $capture=Get-Content (Join-Path $providerRoot last-request.json) -Raw|ConvertFrom-Json -Depth 60;$sent=$capture.messages[-1].content|ConvertFrom-Json;Check ($sent.offset-ge$offset-and$sent.previous_digest.summary-eq$digest.summary-and$sent.next_offset-eq$sent.total_bytes) 'resume sends only remaining source plus prior derived digest'
 $memories=@((Api '/api/memories').memories|Where-Object origin -eq library_compaction);Check ($memories.Count-eq1-and$memories[0].sources[0].id-eq'long-memory'-and$memories[0].sources[0].revision-eq1) 'only one final summary is published with its exact original source'
 $raw=(Api '/api/archive' @{id='long-memory'}).records[0];Check ($raw.revision-eq1-and$raw.data.text.StartsWith('LONG_MEMORY_ORIGINAL ')) 'long original is never shortened or rewritten'
 Stop-Backend;Check (!([Text.Encoding]::UTF8.GetString([IO.File]::ReadAllBytes((Join-Path $cfg.dataRoot archive/records.sqlite))).Contains($digest.summary))) 'partial and final digest payloads remain encrypted'
 @{completed=$true;checks=$checks;root=$root;actual_paid_model_calls=0}|ConvertTo-Json|Set-Content (Join-Path $root acceptance.json);Write-Output "Compaction chunks passed: $checks checks. Evidence: $root"
}finally{foreach($p in @($service,$provider)){if($p){$p.Refresh();if(!$p.HasExited){Stop-Process -Id $p.Id}}}}
